// --- Animation Wrapper Component ---

type AnimationType = "slide" | "pop" | "glide" | "fade";

const AnimatedItem: React.FC<{
  children: React.ReactNode;
  delay: number;
  type: AnimationType;
  width: number;
}> = ({ children, delay, type, width }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Adjust frame based on delay
  const activeFrame = Math.max(0, frame - delay);

  // 1. Slide (Plate)
  const slideOpacity = interpolate(activeFrame, [0, 10], [0, 1], { extrapolateRight: "clamp" });
  const slideX = spring({ frame: activeFrame, fps, config: { damping: 15 }, from: -width * 0.5, to: 0 });

  // 2. Pop (Ticket)
  const popScale = spring({ frame: activeFrame, fps, config: { stiffness: 200, damping: 10 } });
  const popOpacity = interpolate(activeFrame, [0, 5], [0, 1], { extrapolateRight: "clamp" });

  // 3. Glide (Car)
  const glideX = interpolate(activeFrame, [0, 25], [-width * 0.3, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });
  const glideOpacity = interpolate(activeFrame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // 4. Fade & Scale (Clothes)
  const fadeScale = interpolate(activeFrame, [0, 20], [0.8, 1], { extrapolateRight: "clamp" });
  const fadeOpacity = interpolate(activeFrame, [0, 20], [0, 1], { extrapolateRight: "clamp" });

  let style: React.CSSProperties = { opacity: 1 };

  if (type === "slide") {
    style = { opacity: slideOpacity, transform: `translateX(${slideX}px)` };
  } else if (type === "pop") {
    style = { opacity: popOpacity, transform: `scale(${popScale})` };
  } else if (type === "glide") {
    style = { opacity: glideOpacity, transform: `translateX(${glideX}px)` };
  } else if (type === "fade") {
    style = { opacity: fadeOpacity, transform: `scale(${fadeScale})` };
  }

  return <div style={{ ...style, transition: "none" }}>{children}</div>;
};

// --- Main Component ---

const PurchaseIcons: React.FC<PurchaseIconsProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = false,
  iconColor = "#1a1a1a",
  durationInSeconds = 3,
  iconSize = 120,
  spacing = 60,
}) => {
  useFontLoader(["Inter"]); // Load standard font even if unused for safety

  const { width: canvasWidth, height: canvasHeight, fps } = useVideoConfig();
  const frame = useCurrentFrame();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing Logic
  // Total duration < 3s, so we stagger them quickly.
  // Delay calculation (in frames)
  const startDelay = 5;
  const interval = 15; // Gap between items appearing

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        gap: spacing,
        transition: "none",
      }}
    >
      {/* 1. Plate (Slide In) */}
      <AnimatedItem delay={startDelay} type="slide" width={iconSize}>
        <PlateIcon size={iconSize} color={iconColor} />
      </AnimatedItem>

      {/* 2. Ticket (Pop/Bounce) */}
      <AnimatedItem delay={startDelay + interval} type="pop" width={iconSize}>
        <TicketIcon size={iconSize} color={iconColor} />
      </AnimatedItem>

      {/* 3. Car (Glide In) */}
      <AnimatedItem delay={startDelay + interval * 2} type="glide" width={iconSize}>
        <CarIcon size={iconSize} color={iconColor} />
      </AnimatedItem>

      {/* 4. Clothes (Fade & Scale) */}
      <AnimatedItem delay={startDelay + interval * 3} type="fade" width={iconSize}>
        <ClothesIcon size={iconSize} color={iconColor} />
      </AnimatedItem>
    </AbsoluteFill>
  );
};

export default PurchaseIcons;